// Auto-synchronized directly from official Manav Rachna University Timetable (mru.edupage.org)
import 'package:intl/intl.dart';
import 'package:shared_preferences/shared_preferences.dart';

class TimetablePeriodSlot {
  final int period;
  final String startTime;
  final String endTime;
  final String label;

  const TimetablePeriodSlot(this.period, this.startTime, this.endTime, this.label);
}

class TimetableSlotEntry {
  final String subject;
  final List<String> teachers;
  final List<String> rooms;
  final String group;
  final int durationPeriods;

  const TimetableSlotEntry({
    required this.subject,
    required this.teachers,
    required this.rooms,
    required this.group,
    this.durationPeriods = 1,
  });

  factory TimetableSlotEntry.fromJson(Map<String, dynamic> json) {
    return TimetableSlotEntry(
      subject: json['subject'] as String? ?? '',
      teachers: List<String>.from(json['teachers'] ?? []),
      rooms: List<String>.from(json['rooms'] ?? []),
      group: json['group'] as String? ?? '',
      durationPeriods: (json['durationPeriods'] as num?)?.toInt() ?? 1,
    );
  }

  Map<String, dynamic> toJson() => {
    'subject': subject,
    'teachers': teachers,
    'rooms': rooms,
    'group': group,
    'durationPeriods': durationPeriods,
  };
}

