  static List<String> get availableClasses => rawClassData.keys.toList()..sort();
  static List<String> get availableTeachers => rawTeacherData.keys.toList()..sort();

  /// Resolves the student's exact class from their profile metadata.
  static String resolveSection({
    String? program,
    String? branch,
    String? semester,
    String? section,
  }) {
    if (section != null && section.trim().isNotEmpty) {
      final clean = section.trim();
      if (rawClassData.containsKey(clean)) return clean;
      final match = rawClassData.keys.firstWhere(
        (k) => k.toLowerCase() == clean.toLowerCase() || k.toLowerCase().contains(clean.toLowerCase()),
        orElse: () => '',
      );
      if (match.isNotEmpty) return match;
    }

    final b = (branch ?? '').toLowerCase();
    final sem = (semester ?? '5').replaceAll(RegExp(r'[^0-9]'), '');
    final semNum = sem.isEmpty ? '5' : sem;

    String branchPrefix = 'CSE';
    if (b.contains('cst') || b.contains('information')) {
      branchPrefix = 'CST';
    } else if (b.contains('ai') || b.contains('machine')) {
      branchPrefix = 'AIML';
    } else if (b.contains('data') || b.contains('ds')) {
      branchPrefix = 'DS';
    } else if (b.contains('cyber') || b.contains('security')) {
      branchPrefix = 'Cyber';
    } else if (b.contains('ece') || b.contains('electronic')) {
      branchPrefix = 'ECE';
    } else if (b.contains('me') || b.contains('mechanical')) {
      branchPrefix = 'ME';
    } else if (b.contains('law')) {
      branchPrefix = 'LAW';
    } else if (b.contains('bba') || b.contains('business')) {
      branchPrefix = 'BBA';
    }

    final candidate = '$branchPrefix $semNum' 'A';
    if (rawClassData.containsKey(candidate)) return candidate;

    final fuzzy = rawClassData.keys.firstWhere(
      (k) => k.toLowerCase().contains(branchPrefix.toLowerCase()) && k.contains(semNum),
      orElse: () => 'CSE 5A',
    );
    return fuzzy;
  }

  /// Resolves the teacher name or faculty member.
  static String resolveTeacher(String? teacherQuery) {
    if (teacherQuery == null || teacherQuery.trim().isEmpty) return 'PRINIMA GUPTA';
    final clean = teacherQuery.trim();
    if (rawTeacherData.containsKey(clean)) return clean;
    final match = rawTeacherData.keys.firstWhere(
      (k) => k.toLowerCase() == clean.toLowerCase() || k.toLowerCase().contains(clean.toLowerCase()) || clean.toLowerCase().contains(k.toLowerCase()),
      orElse: () => 'PRINIMA GUPTA',
    );
    return match;
  }

  static Map<String, Map<int, List<TimetableSlotEntry>>> getClassSchedule(String className) {
    final cleanName = className.trim();
    var data = rawClassData[cleanName];
    if (data == null) {
      final match = rawClassData.keys.firstWhere(
        (k) => k.toLowerCase() == cleanName.toLowerCase() || k.toLowerCase().contains(cleanName.toLowerCase()),
        orElse: () => 'CSE 5A',
      );
      data = rawClassData[match] ?? rawClassData['CSE 5A'];
    }

    final result = <String, Map<int, List<TimetableSlotEntry>>>{};
    for (final day in days) {
      result[day] = {};
      final dayData = data[day] as Map<String, dynamic>? ?? {};
      for (int p = 1; p <= 10; p++) {
        final entriesRaw = dayData[p.toString()] as List<dynamic>? ?? [];
        result[day]![p] = entriesRaw
            .map((e) => TimetableSlotEntry.fromJson(Map<String, dynamic>.from(e as Map)))
            .toList();
      }
    }
    return result;
  }

  static Map<String, Map<int, List<TimetableSlotEntry>>> getTeacherSchedule(String teacherName) {
    final cleanName = resolveTeacher(teacherName);
    var data = rawTeacherData[cleanName];
    if (data == null) {
      data = rawTeacherData['PRINIMA GUPTA'] ?? {};
    }

    final result = <String, Map<int, List<TimetableSlotEntry>>>{};
    for (final day in days) {
      result[day] = {};
      final dayData = data[day] as Map<String, dynamic>? ?? {};
      for (int p = 1; p <= 10; p++) {
        final entriesRaw = dayData[p.toString()] as List<dynamic>? ?? [];
        result[day]![p] = entriesRaw
            .map((e) => TimetableSlotEntry.fromJson(Map<String, dynamic>.from(e as Map)))
            .toList();
      }
    }
    return result;
  }

  static DateTime _lastSyncedAt = DateTime.now();
  static final Map<String, DateTime> _sectionSyncMap = {};

  static DateTime get lastSyncedAt => _lastSyncedAt;

  static String get lastSyncedFormatted {
    return DateFormat('MMM d, yyyy • h:mm a').format(_lastSyncedAt);
  }

  static String getSectionLastSyncedFormatted(String section) {
    final dt = _sectionSyncMap[section] ?? _lastSyncedAt;
    return DateFormat('MMM d, yyyy • h:mm a').format(dt);
  }

  static Future<void> initSyncTime() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      final savedIso = prefs.getString('mru_timetable_last_synced_at');
      if (savedIso != null) {
        _lastSyncedAt = DateTime.tryParse(savedIso) ?? DateTime.now();
      }
      for (final key in prefs.getKeys()) {
        if (key.startsWith('mru_sync_sec_')) {
          final sec = key.replaceFirst('mru_sync_sec_', '');
          final val = prefs.getString(key);
          if (val != null) {
            _sectionSyncMap[sec] = DateTime.tryParse(val) ?? DateTime.now();
          }
        }
      }
    } catch (_) {}
  }

  static Future<void> updateSyncTime(DateTime dt, {String? section}) async {
    _lastSyncedAt = dt;
    if (section != null) {
      _sectionSyncMap[section] = dt;
    }
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('mru_timetable_last_synced_at', dt.toIso8601String());
      if (section != null) {
        await prefs.setString('mru_sync_sec_$section', dt.toIso8601String());
      }
    } catch (_) {}
  }

  static int getTeacherSlotCount(String teacherName) {
    final clean = resolveTeacher(teacherName);
    final data = rawTeacherData[clean];
    if (data == null) return 0;
    int count = 0;
    for (final day in days) {
      final dayData = data[day] as Map<String, dynamic>? ?? {};
      for (int p = 1; p <= 10; p++) {
        final entries = dayData[p.toString()] as List<dynamic>? ?? [];
        count += entries.length;
      }
    }
    return count;
  }

  static Future<String?> getSavedSelectedTeacher() async {
    try {
      final prefs = await SharedPreferences.getInstance();
      return prefs.getString('mru_saved_selected_teacher');
    } catch (_) {
      return null;
    }
  }

  static Future<void> saveSelectedTeacher(String teacherName) async {
    try {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setString('mru_saved_selected_teacher', teacherName);
    } catch (_) {}
  }
}
